#include "KS/SRC/ks/igo_widget_shared.h"
#include "NGL/PS2/ngl_ps2_shared.h"

class TextString;

class PhotoWidget : public IGOWidget
{
private:
	static const float TIME_SHOWN;
	static const float TIME_FADE_IN;
	static const float TIME_FADE_OUT;

	PanelQuad *		borderPQ;
	int				borderCenterX, borderCenterY, borderZ;
	nglTexture *	photoTexture;
	nglQuad			photoQuad, darkQuad;
	float			darkFade;
	float			fadeOutAlpha;

	float			shownTimer;
	bool			timed;

	int				photoNum;
	TextString *	pointText;
	int				score, * scorePtr;

private:
	virtual void SetPointText(void);

public:
	virtual ~PhotoWidget();
	virtual void Update(const float dt);
	void Hide(void);
};

const float PhotoWidget::TIME_SHOWN = 5.0f;
const float PhotoWidget::TIME_FADE_IN = 4.0f;
const float PhotoWidget::TIME_FADE_OUT = 1.0f;

__asm__(".equ Update__9IGOWidgetf, 0x00164660");
__asm__(".equ Hide__11PhotoWidget, 0x0016B000");
__asm__(".equ SetPointText__11PhotoWidget, 0x0016B290");

void PhotoWidget::Update(const float dt)
{
	float	fadeTimeRemaining = 0.0f;

	IGOWidget::Update(dt);

	if (timed && photoTexture)
	{
		shownTimer -= dt;

			fadeOutAlpha = 1.0f;

		if (shownTimer <= 0.0f)
		{
			shownTimer = 0.0f;
			Hide();
		}
	}

	if (scorePtr && (*scorePtr != score))
	{
		score = *scorePtr;
		SetPointText();
	}

	if (timed)
	{
		if (shownTimer > 0.0f)
		{
			fadeTimeRemaining = TIME_FADE_IN-(TIME_SHOWN-shownTimer);
			if (fadeTimeRemaining > TIME_FADE_IN) fadeTimeRemaining = TIME_FADE_IN;
			if (fadeTimeRemaining < 0.0f) fadeTimeRemaining = 0.0f;

			darkFade = fadeTimeRemaining/TIME_FADE_IN;
		}
	}
}
